import * as T from 'three';
import {GLTFLoader} from '../vendor/loaders/GLTFLoader.js';
import {OrbitControls} from '../vendor/OrbitControls.js';
import {cameraOwnsPointer,sandboxWheel} from '../vendor/sandbox-camera.mjs';
import {createMoonSimulation} from './moon-simulation.mjs';

const $=s=>document.querySelector(s),key='moon-simulator-v1';
const renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.setClearColor('#c8cbd0');renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;$('#world').append(renderer.domElement);
const scene=new T.Scene(),camera=new T.PerspectiveCamera(38,1,.1,300),orbit=new OrbitControls(camera,renderer.domElement);
orbit.mouseButtons={LEFT:T.MOUSE.ROTATE,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.touches={ONE:T.TOUCH.ROTATE,TWO:T.TOUCH.DOLLY_PAN};orbit.minDistance=4;orbit.maxDistance=140;orbit.maxPolarAngle=Math.PI*.47;orbit.enableDamping=false;
renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();e.stopImmediatePropagation();sandboxWheel(T,camera,orbit,e);},{capture:true,passive:false});
scene.add(new T.HemisphereLight('#e1ecff','#5c5862',2.2));const sun=new T.DirectionalLight('#fff0da',3.1);sun.position.set(-15,25,10);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-25,right:25,top:25,bottom:-25,near:1,far:90});sun.shadow.bias=-.0005;scene.add(sun);
const stage=new T.Mesh(new T.PlaneGeometry(400,400),new T.MeshStandardMaterial({color:'#bcc0c6',roughness:1}));stage.rotation.x=-Math.PI/2;stage.position.y=-1.05;stage.receiveShadow=true;scene.add(stage);
const loader=new GLTFLoader(),assets=new Map();let root,astronaut,cargo,simulation,running=true,speed=1,busy=false,last=performance.now(),lastRead=0,lastSave=0,selected='astronaut';
const labels={'idle':'Choosing the next delivery','to-source':'Walking to the supply depot',collect:'Collecting supplies','to-destination':'Carrying supplies to the habitat',deliver:'Restocking habitat supplies','to-rest':'Returning to the habitat',rest:'Resting at the habitat'};
const notes={astronaut:'Field missions collect samples; habitat service takes priority when supplies run low.',habitat:'Receives and consumes supply units. Interior life and pressure are not simulated.',depot:'Monthly rockets replenish this stock. No continuous outside resupply.',reactor:'Nuclear power site: the authored heat-pipe concept is visual. Generation and demand are next.',science:'A field mission collects one sample here after travel and service time.',landing:'Monthly Earth exchange. Supplies arrive, lab samples return to Earth, and the crew rotates at base. Flight animation is not yet implemented.',communications:'Authored communications dish. Signal simulation is a later step.',rover:'Parked surface robot. Driving is a later step.'};
function fit(){const narrow=innerWidth<700;orbit.target.set(narrow?0:3,0,narrow?2:0);camera.position.copy(orbit.target).add(new T.Vector3(26,28,35).multiplyScalar(narrow?2:1));orbit.update();}
function resize(){renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();}addEventListener('resize',resize);resize();fit();
function save(){if(!simulation||busy)return;try{localStorage.setItem(key,JSON.stringify({...simulation.snapshot(),camera:{aspect:camera.aspect,position:camera.position.toArray(),target:orbit.target.toArray()},running}));$('#save').textContent='Saved on this device · separate from Ranch';}catch{$('#save').textContent='Device storage unavailable · this session only';}}
function mesh(geometry,color){return new T.Mesh(geometry,new T.MeshStandardMaterial({color,roughness:.9}));}
function disposeRoot(){if(!root)return;root.traverse(o=>{if(o.isMesh&&!o.userData.library){o.geometry.dispose();for(const m of Array.isArray(o.material)?o.material:[o.material])m.dispose();}});scene.remove(root);}
function model(id){const body=assets.get(id).clone(true);body.traverse(o=>{if(o.isMesh){o.userData.library=true;o.castShadow=true;o.receiveShadow=true;}});return body;}
async function build(seed,saved){busy=true;$('#new').disabled=true;$('#status').textContent='Preparing lunar outpost…';
 try{if(!assets.size)await Promise.all(['ME-072','ME-066','ME-005','ME-006','ME-007','ME-008','ME-010','ME-041','ME-048','ME-070'].map(async id=>assets.set(id,(await loader.loadAsync(`assets/${id}.glb`)).scene)));
 simulation=createMoonSimulation(seed,saved);disposeRoot();root=new T.Group();scene.add(root);const p=simulation.plan;
 const ground=mesh(new T.CylinderGeometry(p.radius,p.radius,1,6),'#94969b');ground.position.y=-.5;ground.receiveShadow=true;root.add(ground);
 // Crater bowls stay outside the service corridor and every building footprint.
 for(const c of p.craters){const bowl=mesh(new T.CircleGeometry(c.radius,28),'#75787f');bowl.rotation.x=-Math.PI/2;bowl.position.set(c.x,.012,c.z);root.add(bowl);const rim=mesh(new T.TorusGeometry(c.radius,.12,6,28),'#aaacb0');rim.rotation.x=-Math.PI/2;rim.position.set(c.x,.045,c.z);root.add(rim);}
 for(const o of p.placements){const body=model(o.asset);body.position.set(o.x,0,o.z);body.userData.selection=o.id;root.add(body);}
 const route=[p.destination,p.corridor,p.source,p.corridor,p.field];for(let i=1;i<route.length;i++){const a=route[i-1],b=route[i],length=Math.hypot(b.x-a.x,b.z-a.z),path=mesh(new T.PlaneGeometry(.85,length),'#aeb0b3');path.rotation.set(-Math.PI/2,0,-Math.atan2(b.x-a.x,b.z-a.z));path.position.set((a.x+b.x)/2,.018,(a.z+b.z)/2);root.add(path);}
 for(const x of [p.source.x,p.destination.x]){const beacon=model('ME-010');beacon.position.set(x,0,7.8);root.add(beacon);}
 astronaut=model('ME-008');astronaut.userData.selection='astronaut';root.add(astronaut);cargo=mesh(new T.BoxGeometry(.38,.3,.3),'#ca7748');cargo.position.set(.55,.85,.1);astronaut.add(cargo);
 $('#location').textContent=`Outpost ${seed} · 36 m parcel`;$('#status').textContent='';if(saved?.camera&&Math.abs((saved.camera.aspect??1.78)-camera.aspect)<.3){camera.position.fromArray(saved.camera.position);orbit.target.fromArray(saved.camera.target);orbit.update();}else fit();selected='astronaut';readout();
 }catch(e){$('#status').textContent='Could not load the Moon outpost. '+e.message;console.error(e);}finally{busy=false;$('#new').disabled=false;last=performance.now();}}
function readout(){if(!simulation)return;const {state,worker}=simulation,site=state.sites[0];$('#activity').textContent=running?(worker.job?.kind==='science'?({'to-source':'Walking to the geology site',collect:'Collecting a geological sample','to-destination':'Returning the sample to the lab',deliver:'Cataloguing the sample'}[worker.phase]||labels[worker.phase]):labels[worker.phase]||worker.phase):'Simulation paused';$('#habitat').textContent=`${site.supplies.toFixed(1)} / ${site.capacity}`;$('#stock').textContent=state.stock.supplies.toFixed(1);$('#cargo').textContent=(worker.job?.load||0).toFixed(0)+(worker.job?.kind==='science'?' sample':' supplies');$('#samples').textContent=state.science.atLab;$('#returned').textContent=state.science.returned;$('#rocket').textContent=`Day ${Math.floor(state.seconds/6)%30+1} · Month ${Math.floor(state.seconds/180)+1} · Rocket in ${Math.ceil((180-state.seconds%180)/6)} days`+(state.rocket.visits?` · Last return: ${state.rocket.lastReturn} samples`+(state.rocket.lastCrew?` · ${state.rocket.lastCrew.outgoing} → ${state.rocket.lastCrew.incoming}`:''):'');$('#jobs').textContent=state.jobs;$('#level').style.width=`${site.supplies/site.capacity*100}%`;$('#selected').textContent=selected==='astronaut'?worker.name+' · field scientist':simulation.plan.placements.find(p=>p.id===selected)?.label||'Outpost';$('#selection-note').textContent=notes[selected];$('#ledger').textContent=`Used ${state.used.supplies.toFixed(1)} · supplied externally ${state.replenished.supplies.toFixed(1)} · accounting difference ${Math.abs(simulation.balance()).toFixed(6)}`;renderer.domElement.dataset.simulation=JSON.stringify({family:'moon',science:state.science,rocket:state.rocket,seed:simulation.plan.seed,phase:worker.phase,position:worker.position,seconds:state.seconds,deliveries:state.jobs,habitat:site.supplies,stock:state.stock.supplies,cargo:worker.job?.load||0,balance:simulation.balance()});}
$('#speed').onchange=e=>speed=Number(e.target.value);$('#pause').onclick=()=>{running=!running;$('#pause').textContent=running?'Pause':'Resume';readout();save();};$('#fit').onclick=fit;$('#new').onclick=async()=>{await build((simulation?.plan.seed||214)+1);save();};
function panel(open){$('#inspector').hidden=!open;$('#details').setAttribute('aria-expanded',String(open));}$('#details').onclick=()=>panel($('#inspector').hidden);$('#close').onclick=()=>panel(false);if(innerWidth<700)panel(false);
let down;renderer.domElement.addEventListener('pointerdown',e=>{down=cameraOwnsPointer(e)?null:{x:e.clientX,y:e.clientY};});renderer.domElement.addEventListener('pointercancel',()=>down=null);renderer.domElement.addEventListener('pointerup',e=>{if(!root||busy||!down||Math.hypot(e.clientX-down.x,e.clientY-down.y)>5){down=null;return;}down=null;const ray=new T.Raycaster();ray.setFromCamera(new T.Vector2(e.clientX/innerWidth*2-1,1-e.clientY/innerHeight*2),camera);for(const hit of ray.intersectObject(root,true)){let o=hit.object;while(o&&!o.userData.selection)o=o.parent;if(o){selected=o.userData.selection;panel(true);readout();break;}}});
// Use the existing appearance loader and move its button into the one toolbar.
const observer=new MutationObserver(()=>{const b=$('#app-settings-toggle');if(b&&b.parentElement!==$('#appearance-slot')){$('#appearance-slot').append(b);observer.disconnect();}});observer.observe(document.body,{childList:true,subtree:true});
let saved;try{const candidate=JSON.parse(localStorage.getItem(key));if(candidate?.version===1&&Number.isInteger(candidate.seed)&&candidate.state?.sites?.length===1&&candidate.worker)saved=candidate;}catch{}if(saved?.running===false){running=false;$('#pause').textContent='Resume';}await build(saved?.seed??214,saved);
function frame(now){const dt=Math.min(.05,Math.max(0,(now-last)/1000));last=now;if(simulation&&!busy){if(running&&!document.hidden)simulation.update(dt*speed);const w=simulation.worker;astronaut.position.set(w.position.x,0,w.position.z);astronaut.rotation.y=w.heading||0;cargo.visible=!!w.job?.load;if(now-lastRead>250){readout();lastRead=now;}if(now-lastSave>3000){save();lastSave=now;}}renderer.render(scene,camera);requestAnimationFrame(frame);}requestAnimationFrame(frame);addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden)save();});
